INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ef',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss biopolitics and the body at B2","Use Biopolitik vocabulary","Talk about Foucault''s biopolitics, body governance, and biopower in Germany"],"explanation":{"intro":"Biopolitics vocabulary covers Foucault''s biopolitics, body governance, and biopower at B2.","culturalNote":"Biopolitik und Körper: Key: Michel Foucault — Biopolitik (biopolitics — Discipline and Punish 1975, History of Sexuality 1978 — ''management of life'' — power over populations as biological entities). Biopower: Disziplinarmacht (disciplinary power — control over individual bodies — schools, hospitals, prisons) + Biomacht (biopolitics proper — population management — fertility, mortality, health, migration). Giorgio Agamben — bare life (nacktes Leben — homo sacer — sovereign power and biopolitics). Germany: Eugenik (eugenics) history — NS Rassenhygiene — impact on German bioethics. Körperpolitik (body politics — abortion, euthanasia, drugs, gender reassignment — state regulation of bodies). COVID-19 as biopolitical event (lockdowns, vaccination mandates, mask mandates). Key: Biomacht as positive (promote life) and negative (let die). Biotechnologie. Transhumanism."},"examples":[{"german":"Foucaults Konzept der Biomacht beschreibt eine Verschiebung in der modernen Herrschaftsform: Während die vormoderne Souveränität das Recht des Sterbenlassens oder Tötens ausübte, richtet sich die moderne Biopolitik auf die Regulierung und Optimierung des Lebens von Bevölkerungen — Geburtenrate, Sterblichkeit, Morbidität, Sexualität — als Gegenstand staatlicher Verwaltung.","english":"Foucault''s concept of biopower describes a shift in modern form of rule: while premodern sovereignty exercised the right to let die or kill, modern biopolitics focuses on the regulation and optimisation of the life of populations — birth rate, mortality, morbidity, sexuality — as an object of state administration."},{"german":"Biopolitische Analysen haben für das Verständnis von Pandemiepolitik erhebliche Relevanz: Maßnahmen wie Quarantäne, Impfpflichten und Bewegungseinschränkungen sind nicht nur epidemiologische Instrumente, sondern Formen staatlicher Verfügung über Körper, die den Konflikt zwischen kollektivem Gesundheitsschutz und individueller Freiheit als biopolitisches Grundproblem der Moderne sichtbar machen.","english":"Biopolitical analyses have considerable relevance for the understanding of pandemic policy: measures such as quarantine, vaccination mandates, and movement restrictions are not only epidemiological instruments, but forms of state disposition over bodies, which make visible the conflict between collective health protection and individual freedom as a fundamental biopolitical problem of modernity."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Foucault''s biopolitics, biopower, and COVID as biopolitical event at B2."}}',
'{"items":[{"word":"die Biomacht","translation":"biopower","pronunciation":"dee BEE-oh-makht","example":"Foucaults Biomacht."},{"word":"die Sterblichkeit","translation":"mortality","pronunciation":"dee SHTERP-likh-kyt","example":"Bevölkerungssterblichkeit."},{"word":"die Morbidität","translation":"morbidity","pronunciation":"dee mor-bi-di-TÄT","example":"Morbidität kontrollieren."},{"word":"die Verfügung","translation":"disposition/control","pronunciation":"dee fer-FÜ-goong","example":"Staatliche Verfügung über Körper."},{"word":"vormodern","translation":"premodern","pronunciation":"FOR-mo-dern","example":"Vormoderne Souveränität."},{"word":"ausüben","translation":"to exercise (power)","pronunciation":"OWS-ü-ben","example":"Recht ausüben."}]}',
'{"title":"Sich auf X richten — to focus on X / be directed at X","pattern":"sich auf X richten = to focus on X, to be directed at X (sich richten auf + accusative — marks where a force, policy, or attention is directed; reflexive: richtet sich auf = directs itself at)","explanation":"Sich richten auf = to direct/focus on (richten = to direct, align; reflexive sich richten auf + accusative = to be directed at, to focus on X). Die moderne Biopolitik richtet sich auf die Regulierung des Lebens = modern biopolitics directs itself toward the regulation of life. The phrase marks the object or target of a power, movement, or force. Compare: zielen auf (to aim at — more intentional/strategic), abzielen auf (to target — deliberate aim), auf X ausgerichtet sein (to be aligned toward — more positional/structural), fokussieren auf (to focus on — more cognitive/attentional), betreffen (to concern/affect — without directional force).","examples":[{"sentence":"Die Kritik richtet sich auf die Struktur des Systems.","translation":"The critique focuses on the structure of the system."},{"sentence":"Die Maßnahme richtet sich auf die Reduzierung von Emissionen.","translation":"The measure is directed at reducing emissions."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Morbidität'' means?","options":["morbidity","illness","disease","sickness"],"correctAnswer":"morbidity"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Foucault''s concept of biopower describes a shift in modern form of rule: while premodern sovereignty exercised the right to let die or kill, modern biopolitics focuses on the regulation and optimisation of the life of populations — birth rate, mortality, morbidity, sexuality — as an object of state administration.","options":["Foucaults Konzept der Biomacht beschreibt eine Verschiebung in der modernen Herrschaftsform: Während die vormoderne Souveränität das Recht des Sterbenlassens oder Tötens ausübte, richtet sich die moderne Biopolitik auf die Regulierung und Optimierung des Lebens von Bevölkerungen — Geburtenrate, Sterblichkeit, Morbidität, Sexualität — als Gegenstand staatlicher Verwaltung.","Foucaults Biomacht beschreibt, wie Staaten Bevölkerungen biologisch verwalten.","Moderne Herrschaft kontrolliert nicht mehr nur Straftaten, sondern Körper und Leben.","Biopolitik bedeutet: Der Staat verwaltet das Leben der Bevölkerung als Ganzes."],"correctAnswer":"Foucaults Konzept der Biomacht beschreibt eine Verschiebung in der modernen Herrschaftsform: Während die vormoderne Souveränität das Recht des Sterbenlassens oder Tötens ausübte, richtet sich die moderne Biopolitik auf die Regulierung und Optimierung des Lebens von Bevölkerungen — Geburtenrate, Sterblichkeit, Morbidität, Sexualität — als Gegenstand staatlicher Verwaltung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Kritik richtet sich auf die Struktur des ___.","options":["Systems","Problems","Konzepts","Modells"],"correctAnswer":"Systems"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The measure is directed at reducing emissions","wordBankItems":["Die","Maßnahme","richtet","sich","auf","die","Reduzierung","von","Emissionen","."],"correctAnswer":"Die Maßnahme richtet sich auf die Reduzierung von Emissionen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vormodern'' means?","options":["premodern","pre-modern","historical","traditional"],"correctAnswer":"premodern"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002f0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss health policy at B2","Use Gesundheitspolitik vocabulary","Talk about Germany''s healthcare system, statutory health insurance, and reform debates"],"explanation":{"intro":"Health policy vocabulary covers Germany''s dual health insurance system, GKV/PKV debate, and health reform at B2.","culturalNote":"Gesundheitspolitik: Germany: Gesetzliche Krankenversicherung (GKV — statutory health insurance — 73 million insured — ~90% population). Private Krankenversicherung (PKV — ~11% — mainly civil servants, high earners). Bismarck model (1883 — world''s first social health insurance — Otto von Bismarck). Key: Solidarprinzip (solidarity principle — healthy subsidise sick) + Versicherungsprinzip (insurance principle). GKV-Beitragssatz (~16.3% — shared employer/employee). Key debate: Bürgerversicherung (citizens'' insurance — SPD/Greens — merge GKV and PKV) vs. maintain dual system (FDP/CDU). Key problems: Ärztmangel (doctor shortage — rural areas), Fachkräftemangel in Pflege (care worker shortage), rising costs (Kostenexplosion), Überversorgung in cities vs. Unterversorgung rural. Key principle: Sachleistungsprinzip (benefits in kind — not cash reimbursement — German model)."},"examples":[{"german":"Das deutsche Gesundheitssystem basiert auf dem Solidarprinzip der gesetzlichen Krankenversicherung: Nicht die individuelle Risikostruktur bestimmt den Beitrag, sondern die Beitragsbemessungsgrundlage — Einkommen. Diese Umverteilung von Gesunden zu Kranken, von Reichen zu Ärmeren ist das ethische Fundament des Systems — aber auch seine politische Schwachstelle, weil sie die Betragspflichtigen motiviert, in günstigere private Tarife zu wechseln.","english":"The German healthcare system is based on the solidarity principle of statutory health insurance: not the individual risk structure but the contribution assessment basis — income — determines the contribution. This redistribution from healthy to sick, from wealthy to less wealthy, is the ethical foundation of the system — but also its political weak point, because it motivates those liable to contribute to switch to cheaper private tariffs."},{"german":"Die Bürgerversicherungsdebatte polarisiert entlang von Gerechtigkeits- und Effizienzargumenten: Befürworter sehen in einer einheitlichen Versicherungspflicht eine gerechtere Lastenteilung und höhere Finanzierungsstabilität; Gegner befürchten Qualitätseinbußen durch PKV-Abwanderung von Ärzten und höhere Beitragsbelastung für Mittelverdiener. Der Konflikt spiegelt grundlegend unterschiedliche Vorstellungen davon wider, ob Gesundheit ein Gut der Solidargemeinschaft oder eine individuell verantwortete Risikovorsorge ist.","english":"The citizens'' insurance debate polarises along justice and efficiency arguments: proponents see a fairer distribution of burdens and higher financial stability in a uniform insurance obligation; opponents fear quality losses through PKV migration of doctors and higher contribution burden for middle earners. The conflict reflects fundamentally different conceptions of whether health is a good of the solidarity community or individually managed risk provision."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s GKV/PKV system, the solidarity principle, and citizens'' insurance debate at B2."}}',
'{"items":[{"word":"die Beitragsbemessungsgrundlage","translation":"contribution assessment basis","pronunciation":"dee by-TRAKS-beh-mes-oongs-groond-lah-geh","example":"Einkommensbasierte Grundlage."},{"word":"die Umverteilung","translation":"redistribution","pronunciation":"dee OOM-fer-ty-loong","example":"Umverteilung von Gesunden zu Kranken."},{"word":"die Lastenteilung","translation":"burden-sharing","pronunciation":"dee LAS-ten-ty-loong","example":"Gerechte Lastenteilung."},{"word":"polarisieren","translation":"to polarise","pronunciation":"po-la-ri-ZEE-ren","example":"Debatten polarisieren."},{"word":"die Qualitätseinbuße","translation":"quality loss","pronunciation":"dee kva-li-TÄTS-yn-boo-seh","example":"Qualitätseinbußen befürchten."},{"word":"die Risikovorsorge","translation":"risk provision","pronunciation":"dee RI-zi-ko-for-zor-geh","example":"Individuelle Risikovorsorge."}]}',
'{"title":"X spiegelt Y wider — X reflects Y (to reflect/mirror something in)","pattern":"X spiegelt Y wider = X reflects Y (widerspiegeln — separable: spiegelt...wider; to reflect, mirror — spiegeln = to reflect/mirror; wider- = back — the compound marks mirroring)","explanation":"Widerspiegeln = to reflect (separable compound: wider = back/against + spiegeln = to mirror → to mirror back = to reflect). X spiegelt Y wider = X mirrors/reflects Y. Der Konflikt spiegelt unterschiedliche Vorstellungen wider = The conflict reflects different conceptions. The phrase is widely used to say that one phenomenon is a mirror image or expression of something deeper (values, interests, ideologies). Compare: ausdrücken (to express — more direct), zeigen (to show — more general), verkörpern (to embody — more concrete), zum Ausdruck bringen (to give expression to — more deliberate and formal).","examples":[{"sentence":"Die Abstimmung spiegelt die gesellschaftliche Spaltung wider.","translation":"The vote reflects the societal split."},{"sentence":"Das Ergebnis spiegelt jahrelange Vernachlässigung wider.","translation":"The result reflects years of neglect."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Polarisieren'' means?","options":["to polarise","to divide","to split","to separate"],"correctAnswer":"to polarise"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The German healthcare system is based on the solidarity principle of statutory health insurance: not the individual risk structure but the contribution assessment basis — income — determines the contribution. This redistribution from healthy to sick, from wealthy to less wealthy, is the ethical foundation of the system — but also its political weak point, because it motivates those liable to contribute to switch to cheaper private tariffs.","options":["Das deutsche Gesundheitssystem basiert auf dem Solidarprinzip der gesetzlichen Krankenversicherung: Nicht die individuelle Risikostruktur bestimmt den Beitrag, sondern die Beitragsbemessungsgrundlage — Einkommen. Diese Umverteilung von Gesunden zu Kranken, von Reichen zu Ärmeren ist das ethische Fundament des Systems — aber auch seine politische Schwachstelle, weil sie die Betragspflichtigen motiviert, in günstigere private Tarife zu wechseln.","Das GKV-System verteilt Gesundheitskosten nach Einkommen statt nach Risiko.","Solidarprinzip in der GKV: Wer mehr verdient, zahlt mehr — wer krank ist, zahlt nicht mehr.","Das Problem der GKV: Gutverdienende wechseln in die PKV und schwächen die Solidarbasis."],"correctAnswer":"Das deutsche Gesundheitssystem basiert auf dem Solidarprinzip der gesetzlichen Krankenversicherung: Nicht die individuelle Risikostruktur bestimmt den Beitrag, sondern die Beitragsbemessungsgrundlage — Einkommen. Diese Umverteilung von Gesunden zu Kranken, von Reichen zu Ärmeren ist das ethische Fundament des Systems — aber auch seine politische Schwachstelle, weil sie die Betragspflichtigen motiviert, in günstigere private Tarife zu wechseln."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Abstimmung spiegelt die gesellschaftliche Spaltung ___.","options":["wider","ab","vor","ein"],"correctAnswer":"wider"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The result reflects years of neglect","wordBankItems":["Das","Ergebnis","spiegelt","jahrelange","Vernachlässigung","wider","."],"correctAnswer":"Das Ergebnis spiegelt jahrelange Vernachlässigung wider ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Lastenteilung'' means?","options":["burden-sharing","load distribution","cost sharing","distribution of costs"],"correctAnswer":"burden-sharing"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002f1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss pandemic and public health at B2","Use Pandemie und öffentliche Gesundheit vocabulary","Talk about COVID-19 policy, public health debate, and Germany''s pandemic response"],"explanation":{"intro":"Pandemic and public health vocabulary covers COVID-19 policy, public health infrastructure, and pandemic governance at B2.","culturalNote":"Pandemie und öffentliche Gesundheit: Germany: Robert Koch-Institut (RKI — public health institute — pandemic surveillance and response). COVID-19: Germany locked down March 2020. Impfkampagne (vaccination campaign — 2021 — controversies). Impfpflicht debate (vaccination mandate — rejected for general population — only healthcare workers). Kontaktbeschränkungen (contact restrictions). Lockdown controversies. Key: WHO (World Health Organisation). SARS-CoV-2. Long COVID. Bundesgesundheitsminister (Federal Health Minister — Jens Spahn, Karl Lauterbach). Inzidenzzahl (incidence value — 7-day incidence rate per 100,000). Querdenker movement (anti-lockdown, conspiracy theories — approx 30,000 strong). Key tension: Grundrechtsabwägung (balancing constitutional rights — BVerfG reviewed pandemic restrictions). Key concept: Reproduktionszahl (R-Wert — reproduction number). Herdenimmunität (herd immunity). Triage (emergency medical prioritisation)."},"examples":[{"german":"Die Pandemiepolitik hat das Verhältnis zwischen Freiheitsrechten und Gesundheitsschutz als eine der zentralen Grundrechtsabwägungen der Gegenwart in den Vordergrund gerückt: Kontaktbeschränkungen, Versammlungsverbote und Impfpflichten greifen in Grundrechte ein, deren Einschränkung nach dem Verhältnismäßigkeitsprinzip nur gerechtfertigt ist, wenn das verfolgte Ziel — Gesundheitsschutz der Bevölkerung — einen hinreichenden legitimen Zweck begründet.","english":"Pandemic policy has moved to the foreground the relationship between freedom rights and health protection as one of the central constitutional balancing acts of the present: contact restrictions, assembly bans, and vaccination mandates intervene in fundamental rights whose restriction under the principle of proportionality is only justified if the pursued goal — protection of public health — grounds a sufficient legitimate purpose."},{"german":"Pandemiebereitschaft ist ein öffentliches Gut, das chronisch unterproduziert wird: Der Aufbau von Reservekapazitäten — Intensivbetten, Schutzausrüstungsvorräte, epidemiologische Surveillance-Systeme — lohnt sich betriebswirtschaftlich nur im Krisenfall, wird aber in Normalzeiten als ineffiziente Verschwendung wahrgenommen. Die strukturelle Unterinvestition in Gesundheitssysteme ist eine der Ursachen für die Überlastung während der COVID-19-Pandemie.","english":"Pandemic preparedness is a public good that is chronically underproduced: the build-up of reserve capacities — intensive care beds, protective equipment stocks, epidemiological surveillance systems — is only economically worthwhile in crisis, but is perceived as inefficient waste in normal times. The structural underinvestment in health systems is one of the causes for the overloading during the COVID-19 pandemic."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss pandemic policy, constitutional balancing, and public health infrastructure at B2."}}',
'{"items":[{"word":"die Grundrechtsabwägung","translation":"constitutional balancing","pronunciation":"dee GROOND-rekhts-ab-vä-goong","example":"Zentrale Grundrechtsabwägung."},{"word":"in den Vordergrund rücken","translation":"to move to the foreground","pronunciation":"in dayn FOR-der-groond RÜ-ken","example":"In den Vordergrund gerückt."},{"word":"der Verhältnismäßigkeitsgrundsatz","translation":"principle of proportionality","pronunciation":"dayr fer-HÄLT-nis-mä-sikh-kyts-groond-zats","example":"Verhältnismäßigkeitsprinzip anwenden."},{"word":"der Reservekapazität","translation":"reserve capacity","pronunciation":"dayr reh-ZER-veh-ka-pa-tsi-TÄT","example":"Reservekapazitäten aufbauen."},{"word":"chronisch","translation":"chronically","pronunciation":"KROH-nish","example":"Chronisch unterproduziert."},{"word":"die Surveillance","translation":"surveillance","pronunciation":"dee zür-VAY-ans","example":"Epidemiologische Surveillance."}]}',
'{"title":"In den Vordergrund rücken — to move to the foreground (to foreground)","pattern":"etwas rückt X in den Vordergrund = something moves X into the foreground (rücken = to move/shift; in den Vordergrund rücken = to bring to the foreground — marks an increased prominence, urgency, or visibility of X that was previously less salient)","explanation":"In den Vordergrund rücken = to bring into the foreground (rücken = to move, shift; Vordergrund = foreground — as opposed to Hintergrund). Die Pandemiepolitik hat X in den Vordergrund gerückt = pandemic policy has moved X into the foreground. The phrase marks that an issue has become more salient, prominent, or urgent as a result of some event or development. Passive/intransitive: X rückt in den Vordergrund (X moves into the foreground — comes to prominence on its own). Compare: in den Fokus rücken (to come into focus — more visual/attentional), an Relevanz gewinnen (to gain relevance — more gradual), prominent werden (to become prominent — simpler), hervorheben (to highlight/emphasise — deliberate emphasis).","examples":[{"sentence":"Die Krise hat die Frage der sozialen Ungleichheit in den Vordergrund gerückt.","translation":"The crisis has moved the question of social inequality into the foreground."},{"sentence":"Durch den Skandal rückte das Thema Transparenz in den Vordergrund.","translation":"Through the scandal, the topic of transparency moved into the foreground."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Chronisch'' means?","options":["chronically","persistently","permanently","constantly"],"correctAnswer":"chronically"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Pandemic preparedness is a public good that is chronically underproduced: the build-up of reserve capacities — intensive care beds, protective equipment stocks, epidemiological surveillance systems — is only economically worthwhile in crisis, but is perceived as inefficient waste in normal times. The structural underinvestment in health systems is one of the causes for the overloading during the COVID-19 pandemic.","options":["Pandemiebereitschaft ist ein öffentliches Gut, das chronisch unterproduziert wird: Der Aufbau von Reservekapazitäten — Intensivbetten, Schutzausrüstungsvorräte, epidemiologische Surveillance-Systeme — lohnt sich betriebswirtschaftlich nur im Krisenfall, wird aber in Normalzeiten als ineffiziente Verschwendung wahrgenommen. Die strukturelle Unterinvestition in Gesundheitssysteme ist eine der Ursachen für die Überlastung während der COVID-19-Pandemie.","Pandemiebereitschaft ist teuer und bringt in normalen Zeiten nichts — daher wird sie vernachlässigt.","Krankenhäuser hatten zu wenig Kapazitäten wegen jahrelanger Unterfinanzierung.","Wir investieren nicht genug in Pandemievorsorge, weil der Nutzen erst in der Krise sichtbar wird."],"correctAnswer":"Pandemiebereitschaft ist ein öffentliches Gut, das chronisch unterproduziert wird: Der Aufbau von Reservekapazitäten — Intensivbetten, Schutzausrüstungsvorräte, epidemiologische Surveillance-Systeme — lohnt sich betriebswirtschaftlich nur im Krisenfall, wird aber in Normalzeiten als ineffiziente Verschwendung wahrgenommen. Die strukturelle Unterinvestition in Gesundheitssysteme ist eine der Ursachen für die Überlastung während der COVID-19-Pandemie."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Krise hat die Frage der sozialen Ungleichheit in den Vordergrund ___.","options":["gerückt","gebracht","gestellt","genommen"],"correctAnswer":"gerückt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Through the scandal the topic of transparency moved into the foreground","wordBankItems":["Durch","den","Skandal","rückte","das","Thema","Transparenz","in","den","Vordergrund","."],"correctAnswer":"Durch den Skandal rückte das Thema Transparenz in den Vordergrund ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Grundrechtsabwägung'' means?","options":["constitutional balancing","rights balancing","fundamental rights weighing","constitutional rights balance"],"correctAnswer":"constitutional balancing"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002f2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss mental health and society at B2","Use Psychische Gesundheit vocabulary","Talk about mental health stigma, psychotherapy access, and Germany''s mental health system"],"explanation":{"intro":"Mental health and society vocabulary covers mental health stigma, psychotherapy access, and Germany''s mental health system at B2.","culturalNote":"Psychische Gesundheit und Gesellschaft: Germany: 27% of adults affected by mental illness per year (2021 BPtK). Key diagnoses: Depression, Angststörungen (anxiety disorders), PTSD. Psychotherapie (psychotherapy — Germany: Psychotherapeutengesetz 1998 — regulated profession). GKV covers Verhaltenstherapie (CBT), analytische Psychotherapie, tiefenpsychologisch fundierte Psychotherapie. Key problem: Wartezeiten (waiting times — average 6 months for appointment). Stigma debate. Key: Burnout (controversial diagnosis — work-related exhaustion — Germany highest absenteeism from mental illness). Suizid (suicide — 9,000/year Germany — most common violent cause of death). Prävention (prevention). Key debate: Medikalisierung (medicalisation — normal emotions pathologised?). Psychiatriereform (1975 Enquete — deinstitutionalisation). Child and adolescent mental health (Kinder und Jugendpsychiatrie). Social determinants of mental health."},"examples":[{"german":"Psychische Erkrankungen sind die häufigste Ursache für Arbeitsunfähigkeit in Deutschland, werden aber in der gesundheitspolitischen Versorgungsplanung strukturell nachrangig behandelt: Während das Prinzip der Gleichwertigkeit psychischer und körperlicher Gesundheit rechtlich verankert ist, spiegeln Kapazitäten, Wartezeiten und Erstattungssätze diese Gleichwertigkeit nicht wider — eine Versorgungslücke, die mit dem Stigma psychischer Erkrankungen interagiert.","english":"Mental illnesses are the most common cause of incapacity to work in Germany, but are treated as structurally secondary in health policy provision planning: while the principle of equivalence of mental and physical health is legally anchored, capacities, waiting times, and reimbursement rates do not reflect this equivalence — a care gap that interacts with the stigma of mental illnesses."},{"german":"Das Konzept des Burnouts illustriert die Grenze zwischen Pathologisierung und sozialer Diagnose: Als individuelle Erschöpfungskrankheit behandelt, verdeckt Burnout die strukturellen Ursachen in Arbeitsorganisation, Leistungsgesellschaft und fehlendem sozialen Rückhalt — und medikalisiert, was eine sozialpolitische Antwort erfordert. Die Diagnose entlastet Individuen, aber entpolitisiert strukturelle Probleme.","english":"The concept of burnout illustrates the boundary between pathologisation and social diagnosis: treated as an individual exhaustion illness, burnout conceals the structural causes in work organisation, achievement society, and lacking social support — and medicalises what requires a sociopolitical response. The diagnosis relieves individuals, but depoliticises structural problems."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s mental health care gaps, burnout debate, and medicalisation at B2."}}',
'{"items":[{"word":"die Arbeitsunfähigkeit","translation":"incapacity to work","pronunciation":"dee AR-byts-oon-fä-ikh-kyt","example":"Häufigste Ursache für Arbeitsunfähigkeit."},{"word":"nachrangig","translation":"secondary/lower priority","pronunciation":"NAKH-rang-ikh","example":"Strukturell nachrangig."},{"word":"die Versorgungslücke","translation":"care gap","pronunciation":"dee fer-ZOR-goongs-lü-keh","example":"Psychische Versorgungslücke."},{"word":"die Pathologisierung","translation":"pathologisation","pronunciation":"dee pa-to-lo-gi-ZEE-roong","example":"Medikalisierung und Pathologisierung."},{"word":"entpolitisieren","translation":"to depoliticise","pronunciation":"ent-po-li-ti-ZEE-ren","example":"Strukturprobleme entpolitisieren."},{"word":"der Rückhalt","translation":"support","pronunciation":"dayr RÜK-halt","example":"Sozialer Rückhalt."}]}',
'{"title":"X entlastet Y, aber entpolitisiert Z — X relieves Y but depoliticises Z","pattern":"X entlastet Y, aber entpolitisiert Z = X relieves Y, but depoliticises Z (entlasten = to relieve/take the burden off; entpolitisieren = to depoliticise — removes political content from something; the pattern marks the trade-off between individual relief and structural critique)","explanation":"Entlasten = to relieve, take the burden off (ent- = removes/undoes; Last = burden). Entpolitisieren = to depoliticise (ent- = removes; politisieren = to politicise). X entlastet Individuen, aber entpolitisiert strukturelle Probleme = X relieves individuals, but depoliticises structural problems. The pattern marks a trade-off: the diagnosis/narrative/policy offers relief at the individual level, but in doing so removes the political charge from the structural causes. Widely used in critical social science (medicalisation, individualisation, responsibilisation). Compare: individualisieren (to individualise — make an individual''s problem), responsibilisieren (to responsibilise), psychologisieren (to psychologise — attribute to psychology), Strukturen unsichtbar machen (to make structures invisible).","examples":[{"sentence":"Resilienztraining entlastet Mitarbeiter kurzfristig, entpolitisiert aber Arbeitsbedingungen.","translation":"Resilience training relieves employees in the short term, but depoliticises working conditions."},{"sentence":"Die Diagnose entlastet die Betroffenen, entpolitisiert aber strukturelle Ursachen.","translation":"The diagnosis relieves those affected, but depoliticises structural causes."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Nachrangig'' means?","options":["secondary/lower priority","subordinate","minor","less important"],"correctAnswer":"secondary/lower priority"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The concept of burnout illustrates the boundary between pathologisation and social diagnosis: treated as an individual exhaustion illness, burnout conceals the structural causes in work organisation, achievement society, and lacking social support — and medicalises what requires a sociopolitical response. The diagnosis relieves individuals, but depoliticises structural problems.","options":["Das Konzept des Burnouts illustriert die Grenze zwischen Pathologisierung und sozialer Diagnose: Als individuelle Erschöpfungskrankheit behandelt, verdeckt Burnout die strukturellen Ursachen in Arbeitsorganisation, Leistungsgesellschaft und fehlendem sozialen Rückhalt — und medikalisiert, was eine sozialpolitische Antwort erfordert. Die Diagnose entlastet Individuen, aber entpolitisiert strukturelle Probleme.","Burnout ist eine gesellschaftliche Erkrankung, keine individuelle.","Burnout-Diagnosen medikalisieren, was eigentlich ein Strukturproblem der Arbeitswelt ist.","Statt Therapie braucht es strukturelle Reformen der Arbeitsorganisation."],"correctAnswer":"Das Konzept des Burnouts illustriert die Grenze zwischen Pathologisierung und sozialer Diagnose: Als individuelle Erschöpfungskrankheit behandelt, verdeckt Burnout die strukturellen Ursachen in Arbeitsorganisation, Leistungsgesellschaft und fehlendem sozialen Rückhalt — und medikalisiert, was eine sozialpolitische Antwort erfordert. Die Diagnose entlastet Individuen, aber entpolitisiert strukturelle Probleme."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Resilienztraining entlastet Mitarbeiter kurzfristig, entpolitisiert aber ___.","options":["Arbeitsbedingungen","die Struktur","das Problem","den Ursprung"],"correctAnswer":"Arbeitsbedingungen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The diagnosis relieves those affected but depoliticises structural causes","wordBankItems":["Die","Diagnose","entlastet","die","Betroffenen",",","entpolitisiert","aber","strukturelle","Ursachen","."],"correctAnswer":"Die Diagnose entlastet die Betroffenen , entpolitisiert aber strukturelle Ursachen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Entpolitisieren'' means?","options":["to depoliticise","to neutralise","to de-politicise","to remove from politics"],"correctAnswer":"to depoliticise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002f3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss biomedicine and enhancement at B2","Use Biomedizin und Enhancement vocabulary","Talk about human enhancement, neuroenhancement, and bioethics in Germany"],"explanation":{"intro":"Biomedicine and enhancement vocabulary covers human enhancement, neuroethics, and Germany''s bioethical framework at B2.","culturalNote":"Biomedizin und Enhancement: Key: Enhancement (Verbesserung — beyond therapy to optimisation of healthy humans). Types: Neuroenhancement (cognitive enhancement — Ritalin, modafinil use by students), physical enhancement, genetic enhancement. Key debate: Therapy vs. enhancement distinction (Norman Daniels — is it morally relevant?). Transhumanism (Ray Kurzweil — Singularity — uploading consciousness). Germany: Deutscher Ethikrat (German Ethics Council — advisory body — issues statements on bioethical questions). Gentherapie (gene therapy — somatic vs. germline). CRISPR-Cas9 (2020 Nobel Prize — Jennifer Doudna, Emmanuelle Charpentier). Designer babies (Designerbabys — China He Jiankui scandal 2018 — germline editing of twins). Key: Deutschen Ingenieure gewarnt vor Risiken. Leistungsgesellschaft (achievement society) as driver. Medikalisierung des Normalen."},"examples":[{"german":"Die Unterscheidung zwischen Therapie und Enhancement markiert eine ethisch bedeutsame Grenze: Während Therapie darauf zielt, eine Abweichung vom normalen Funktionsniveau zu beheben, zielt Enhancement auf die Steigerung über das Normale hinaus — eine Verschiebung, die Fragen nach Gerechtigkeit aufwirft, wenn Optimierungsmöglichkeiten ungleich verteilt sind und kognitive oder körperliche Überlegenheit käuflich wird.","english":"The distinction between therapy and enhancement marks an ethically significant boundary: while therapy aims to remedy a deviation from normal functional level, enhancement aims at elevation above the normal — a shift that raises questions of justice when optimisation opportunities are unequally distributed and cognitive or physical superiority becomes purchasable."},{"german":"Neuroenhancement illustriert die Spannung zwischen individueller Optimierungsfreiheit und sozialen Gerechtigkeitsnormen: Wenn kognitive Leistungsfähigkeit durch Pharmaka gesteigert werden kann, entsteht ein Druck, der die Grenze zwischen Wahl und Zwang verwischt — nicht durch direkte Prohibition, sondern durch Wettbewerbsnormen in Bildung und Beruf, die den Nicht-Einsatz als Wettbewerbsnachteil erscheinen lassen.","english":"Neuroenhancement illustrates the tension between individual optimisation freedom and social justice norms: when cognitive performance can be enhanced by pharmaceuticals, a pressure arises that blurs the boundary between choice and coercion — not through direct prohibition, but through competitive norms in education and profession, which make non-use appear as a competitive disadvantage."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss therapy vs. enhancement distinction, neuroenhancement pressure, and designer babies at B2."}}',
'{"items":[{"word":"das Enhancement","translation":"enhancement","pronunciation":"dahs EN-hants-ment","example":"Kognitive Enhancement."},{"word":"die Abweichung","translation":"deviation","pronunciation":"dee AB-vy-khoong","example":"Abweichung vom Normalen."},{"word":"käuflich","translation":"purchasable","pronunciation":"KOYF-likh","example":"Käufliche Überlegenheit."},{"word":"verwischen","translation":"to blur","pronunciation":"fer-VISH-en","example":"Grenzen verwischen."},{"word":"die Prohibition","translation":"prohibition","pronunciation":"dee pro-hi-bi-TSYOHN","example":"Direkte Prohibition."},{"word":"erscheinen lassen","translation":"to make appear","pronunciation":"er-SHY-nen LAS-en","example":"Als Nachteil erscheinen lassen."}]}',
'{"title":"Die Grenze zwischen X und Y verwischen — to blur the boundary between X and Y","pattern":"die Grenze zwischen X und Y verwischen = to blur the boundary between X and Y (verwischen = to blur, smear — transitive and intransitive; Grenze = boundary; zwischen X und Y = between X and Y — marks that a previously clear distinction is becoming indistinct)","explanation":"Verwischen = to blur, smear, wipe (related to wischen = to wipe). Die Grenze zwischen X und Y verwischen = to blur the boundary between X and Y. Marks a process of boundary erosion: two things that were once clearly separate become indistinct. Can be active (X verwischt die Grenze = X blurs the boundary) or passive (die Grenze verwischt sich = the boundary blurs). Widely used in ethics, philosophy, politics, and social science. Compare: die Grenze überschreiten (to cross the boundary — still maintains the boundary but moves past it), die Grenze auflösen (to dissolve the boundary — stronger: total disappearance), verschwimmen (to blur — more visual/atmospheric), undeutlich werden (to become indistinct — simpler).","examples":[{"sentence":"Die Technologie verwischt die Grenze zwischen Arbeit und Freizeit.","translation":"Technology blurs the boundary between work and leisure."},{"sentence":"Diese Praxis verwischt die Grenze zwischen Therapie und Enhancement.","translation":"This practice blurs the boundary between therapy and enhancement."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Käuflich'' means?","options":["purchasable","buyable","for sale","commercial"],"correctAnswer":"purchasable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The distinction between therapy and enhancement marks an ethically significant boundary: while therapy aims to remedy a deviation from normal functional level, enhancement aims at elevation above the normal — a shift that raises questions of justice when optimisation opportunities are unequally distributed and cognitive or physical superiority becomes purchasable.","options":["Die Unterscheidung zwischen Therapie und Enhancement markiert eine ethisch bedeutsame Grenze: Während Therapie darauf zielt, eine Abweichung vom normalen Funktionsniveau zu beheben, zielt Enhancement auf die Steigerung über das Normale hinaus — eine Verschiebung, die Fragen nach Gerechtigkeit aufwirft, wenn Optimierungsmöglichkeiten ungleich verteilt sind und kognitive oder körperliche Überlegenheit käuflich wird.","Enhancement geht über Therapie hinaus und optimiert Menschen über ihr natürliches Niveau.","Wenn Enhancement nur für Reiche zugänglich ist, wird Gerechtigkeit zur Frage.","Therapie repariert — Enhancement optimiert. Die Grenze ist ethisch relevant."],"correctAnswer":"Die Unterscheidung zwischen Therapie und Enhancement markiert eine ethisch bedeutsame Grenze: Während Therapie darauf zielt, eine Abweichung vom normalen Funktionsniveau zu beheben, zielt Enhancement auf die Steigerung über das Normale hinaus — eine Verschiebung, die Fragen nach Gerechtigkeit aufwirft, wenn Optimierungsmöglichkeiten ungleich verteilt sind und kognitive oder körperliche Überlegenheit käuflich wird."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Technologie verwischt die Grenze zwischen Arbeit und ___.","options":["Freizeit","Privatleben","Erholung","Urlaub"],"correctAnswer":"Freizeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This practice blurs the boundary between therapy and enhancement","wordBankItems":["Diese","Praxis","verwischt","die","Grenze","zwischen","Therapie","und","Enhancement","."],"correctAnswer":"Diese Praxis verwischt die Grenze zwischen Therapie und Enhancement ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verwischen'' means?","options":["to blur","to smear","to wipe","to obscure"],"correctAnswer":"to blur"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002f4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss genetic engineering and gene therapy at B2","Use Gentechnik und Gentherapie vocabulary","Talk about CRISPR, GMO debate, and Germany''s genetic engineering regulations"],"explanation":{"intro":"Genetic engineering and gene therapy vocabulary covers CRISPR, GMO regulation, and somatic vs. germline editing at B2.","culturalNote":"Gentechnik und Gentherapie: Germany: Gentechnikgesetz (1990 — strict GMO regulation). Key: GM food debate (Monsanto — glyphosate — Genmais — Germany banned many GM crops). CRISPR-Cas9 (gene scissors — 2020 Nobel Chemistry — somatic therapy approved in some applications — germline editing moratorium globally). Key: somatische Gentherapie (somatic gene therapy — modifies non-heritable cells — accepted) vs. Keimbahntherapie (germline editing — modifies heritable DNA — globally rejected except China scandal). Bioethikkommission (ethics advisory body). Germany: Stammzellgesetz (2002 — strict limits on embryonic stem cell research — embryo protection). In-vitro Fertilisation (IVF — permitted). Gendiagnostikgesetz (2010 — genetic testing law — restricts employer/insurance access to genetic data). Key tension: therapeutic potential vs. slippery slope to designer genetics."},"examples":[{"german":"CRISPR-Cas9 hat die Gentherapie von einem theoretischen Versprechen in eine klinische Realität transformiert: Die Präzision und Kosteneffizienz des Verfahrens ermöglicht gezielte Eingriffe in somatische Zellen zur Behandlung monogener Erkrankungen wie Sichelzellanämie — ein Durchbruch, der zugleich die Frage der Keimbahnmanipulation mit neuer Dringlichkeit stellt, weil die technische Machbarkeit die normativen Grenzen unter Druck setzt.","english":"CRISPR-Cas9 has transformed gene therapy from a theoretical promise into a clinical reality: the precision and cost-efficiency of the procedure enables targeted interventions in somatic cells for treating monogenic diseases such as sickle cell anaemia — a breakthrough that simultaneously places the question of germline manipulation with new urgency, because technical feasibility puts normative boundaries under pressure."},{"german":"Die Regulierung von Gentechnik in Lebensmitteln steht vor dem Paradox des asymmetrischen Risikos: Die EU reguliert gentechnisch veränderte Organismen nach dem Herstellungsverfahren — nicht nach den Eigenschaften des Produkts — was dazu führt, dass klassisch durch Mutagenese veränderte Pflanzen (nicht GVO) weniger Regulierung unterliegen als präzisionsgezüchtete CRISPR-Pflanzen. Wissenschaftler kritisieren diese regulatorische Inkongruenz als wissenschaftlich nicht fundiert.","english":"The regulation of genetic engineering in foods faces the paradox of asymmetric risk: the EU regulates genetically modified organisms according to the production method — not the properties of the product — which leads to classical plants modified by mutagenesis (not GMO) being subject to less regulation than precision-bred CRISPR plants. Scientists criticise this regulatory incongruence as scientifically unfounded."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss CRISPR, somatische vs. Keimbahntherapie, and GMO regulation at B2."}}',
'{"items":[{"word":"die Keimbahn","translation":"germline","pronunciation":"dee KYM-bahn","example":"Keimbahnmanipulation."},{"word":"somatisch","translation":"somatic","pronunciation":"zo-MAH-tish","example":"Somatische Gentherapie."},{"word":"die Machbarkeit","translation":"feasibility","pronunciation":"dee MAKH-bar-kyt","example":"Technische Machbarkeit."},{"word":"monogen","translation":"monogenic","pronunciation":"mo-no-GEN","example":"Monogene Erkrankungen."},{"word":"die Mutagenese","translation":"mutagenesis","pronunciation":"dee moo-ta-geh-NEH-zeh","example":"Klassische Mutagenese."},{"word":"inkongruent","translation":"incongruent","pronunciation":"in-kon-groo-ENT","example":"Regulatorische Inkongruenz."}]}',
'{"title":"X setzt Y unter Druck — X puts Y under pressure","pattern":"X setzt Y unter Druck = X puts Y under pressure (unter Druck setzen + accusative — marks that X creates pressure on Y, forces Y to change or respond; Druck = pressure)","explanation":"Unter Druck setzen = to put under pressure (setzen + unter Druck = to put into pressure). X setzt Y unter Druck = X puts Y under pressure. The phrase marks an active pressure dynamic: X (a development, technology, force) applies pressure on Y (a norm, boundary, institution), forcing adaptation or response. Die technische Machbarkeit setzt normative Grenzen unter Druck = technical feasibility puts normative boundaries under pressure. Compare: Y gerät unter Druck (Y comes under pressure — intransitive, no active cause named), X erfordert eine Anpassung von Y (X requires an adaptation of Y — more deliberate), X herausfordern (to challenge — wider scope), belasten (to burden/strain — more weight-based than pressure).","examples":[{"sentence":"Der technologische Wandel setzt traditionelle Berufsbilder unter Druck.","translation":"Technological change puts traditional job profiles under pressure."},{"sentence":"Der Wettbewerb setzt die Marktpreise unter Druck.","translation":"Competition puts market prices under pressure."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Somatisch'' means?","options":["somatic","bodily","cellular","physical"],"correctAnswer":"somatic"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"CRISPR-Cas9 has transformed gene therapy from a theoretical promise into a clinical reality: the precision and cost-efficiency of the procedure enables targeted interventions in somatic cells for treating monogenic diseases such as sickle cell anaemia — a breakthrough that simultaneously places the question of germline manipulation with new urgency, because technical feasibility puts normative boundaries under pressure.","options":["CRISPR-Cas9 hat die Gentherapie von einem theoretischen Versprechen in eine klinische Realität transformiert: Die Präzision und Kosteneffizienz des Verfahrens ermöglicht gezielte Eingriffe in somatische Zellen zur Behandlung monogener Erkrankungen wie Sichelzellanämie — ein Durchbruch, der zugleich die Frage der Keimbahnmanipulation mit neuer Dringlichkeit stellt, weil die technische Machbarkeit die normativen Grenzen unter Druck setzt.","CRISPR macht Gentherapie erstmals klinisch realisierbar — aber öffnet auch die Tür zur Keimbahnmanipulation.","Sichelzellanämie ist mit CRISPR heilbar — aber damit wächst der Druck, auch Keimbahneingriffe zu erlauben.","CRISPR ist präzise und günstig — damit werden normative Grenzen zur Keimbahntherapie fragil."],"correctAnswer":"CRISPR-Cas9 hat die Gentherapie von einem theoretischen Versprechen in eine klinische Realität transformiert: Die Präzision und Kosteneffizienz des Verfahrens ermöglicht gezielte Eingriffe in somatische Zellen zur Behandlung monogener Erkrankungen wie Sichelzellanämie — ein Durchbruch, der zugleich die Frage der Keimbahnmanipulation mit neuer Dringlichkeit stellt, weil die technische Machbarkeit die normativen Grenzen unter Druck setzt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der technologische Wandel setzt traditionelle Berufsbilder unter ___.","options":["Druck","Zwang","Spannung","Stress"],"correctAnswer":"Druck"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Competition puts market prices under pressure","wordBankItems":["Der","Wettbewerb","setzt","die","Marktpreise","unter","Druck","."],"correctAnswer":"Der Wettbewerb setzt die Marktpreise unter Druck ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Machbarkeit'' means?","options":["feasibility","practicability","realizability","achievability"],"correctAnswer":"feasibility"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002f5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss euthanasia and palliative care at B2","Use Sterbehilfe und Palliativversorgung vocabulary","Talk about Germany''s euthanasia law, assisted dying debate, and palliative care"],"explanation":{"intro":"Euthanasia and palliative care vocabulary covers the assisted dying debate, Germany''s legal framework, and palliative care at B2.","culturalNote":"Sterbehilfe und Palliativversorgung: Germany: BVerfG ruling 2020 — right to self-determined death (Recht auf selbstbestimmtes Sterben) as part of general personality right (Art. 2 GG) — struck down §217 StGB (commercialised assisted suicide ban — Bundesverfassungsgericht ruled it unconstitutional). Key: aktive Sterbehilfe (active euthanasia — illegal), passive Sterbehilfe (passive euthanasia — allowed — withdrawal of life support), indirekte Sterbehilfe (indirect euthanasia — palliative sedation — allowed), Beihilfe zum Suizid (assisted suicide — now permitted after BVerfG). Netherlands, Belgium: active euthanasia legal (Sterbehilfe). Switzerland: Dignitas (assisted dying clinic). Germany: Palliativversorgung (palliative care) — hospice movement (Hospizbewegung). Key tension: Selbstbestimmungsrecht (right to self-determination) vs. Lebensschutz (protection of life). NS history: T4 Programm (euthanasia of disabled — 200,000 — haunts the debate). Patientenverfügung (advance directive — living will)."},"examples":[{"german":"Die Sterbehilfedebatte ist in Deutschland untrennbar von der Geschichte des nationalsozialistischen Euthanasieprogramms: Der Missbrauch medizinischer Kompetenzen zur Tötung von Menschen mit Behinderungen unter dem Deckmantel des Lebensunwerts hat die deutsche Bioethik nachhaltig geprägt und erklärt die historisch bedingte Zurückhaltung gegenüber jeder Form von Sterbehilfe, die über Palliativversorgung hinausgeht.","english":"The assisted dying debate in Germany is inseparably linked to the history of the National Socialist euthanasia programme: the misuse of medical competencies to kill people with disabilities under the cover of the concept of ''life unworthy of life'' has permanently shaped German bioethics and explains the historically conditioned restraint towards any form of assisted dying that goes beyond palliative care."},{"german":"Das Bundesverfassungsgericht hat 2020 einen Paradigmenwechsel in der deutschen Sterbehilfejurisprudenz eingeleitet: Mit der Anerkennung eines Rechts auf selbstbestimmtes Sterben als Teil des allgemeinen Persönlichkeitsrechts hat es das Spannungsverhältnis zwischen staatlichem Lebensschutz und individueller Autonomie zugunsten letzterer verschoben — eine Entscheidung, die den Gesetzgeber zur Neuregulierung verpflichtet, ohne die inhaltliche Ausgestaltung festzulegen.","english":"The Federal Constitutional Court initiated a paradigm shift in German assisted dying jurisprudence in 2020: by recognising a right to self-determined death as part of the general personality right, it shifted the tension between state protection of life and individual autonomy in favour of the latter — a decision that obliges the legislator to new regulation, without specifying the substantive design."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s euthanasia law, historical shadow of T4, and BVerfG 2020 ruling at B2."}}',
'{"items":[{"word":"untrennbar","translation":"inseparably","pronunciation":"oon-TREN-bar","example":"Untrennbar verbunden."},{"word":"der Deckmantel","translation":"cover/pretext","pronunciation":"dayr DEK-man-tel","example":"Unter dem Deckmantel."},{"word":"die Zurückhaltung","translation":"restraint","pronunciation":"dee tsoo-RÜK-hal-toong","example":"Historische Zurückhaltung."},{"word":"einleiten","translation":"to initiate","pronunciation":"YN-ly-ten","example":"Paradigmenwechsel einleiten."},{"word":"die Ausgestaltung","translation":"substantive design","pronunciation":"dee OWS-geh-shtal-toong","example":"Inhaltliche Ausgestaltung."},{"word":"verpflichten","translation":"to oblige","pronunciation":"fer-PFLIKH-ten","example":"Gesetzgeber verpflichten."}]}',
'{"title":"X zugunsten Y verschieben — to shift X in favour of Y","pattern":"das Verhältnis/die Gewichtung X zugunsten Y verschieben = to shift X in favour of Y (verschieben = to shift; zugunsten + genitive = in favour of; marks a change in the balance between two competing values, forces, or interests)","explanation":"Zugunsten + genitive = in favour of (zu + Gunsten = to the benefit of). Verschieben = to shift (something from one position to another). Das Spannungsverhältnis zwischen X und Y zugunsten Y verschieben = to shift the tension between X and Y in favour of Y. The phrase marks a movement in balance, not a complete resolution: one side gains, the other loses ground, but both remain. Compare: X den Vorzug geben (to give preference to X), X priorisieren (to prioritise X), X übergewichten (to overweight X — more quantitative), X Vorrang einräumen (to give priority to X — more deliberate).","examples":[{"sentence":"Das Urteil verschiebt das Gleichgewicht zugunsten individueller Freiheitsrechte.","translation":"The ruling shifts the balance in favour of individual freedom rights."},{"sentence":"Die Reform verschiebt die Zuständigkeit zugunsten der Kommunen.","translation":"The reform shifts responsibility in favour of the municipalities."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Einleiten'' means?","options":["to initiate","to begin","to start","to introduce"],"correctAnswer":"to initiate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Federal Constitutional Court initiated a paradigm shift in German assisted dying jurisprudence in 2020: by recognising a right to self-determined death as part of the general personality right, it shifted the tension between state protection of life and individual autonomy in favour of the latter — a decision that obliges the legislator to new regulation, without specifying the substantive design.","options":["Das Bundesverfassungsgericht hat 2020 einen Paradigmenwechsel in der deutschen Sterbehilfejurisprudenz eingeleitet: Mit der Anerkennung eines Rechts auf selbstbestimmtes Sterben als Teil des allgemeinen Persönlichkeitsrechts hat es das Spannungsverhältnis zwischen staatlichem Lebensschutz und individueller Autonomie zugunsten letzterer verschoben — eine Entscheidung, die den Gesetzgeber zur Neuregulierung verpflichtet, ohne die inhaltliche Ausgestaltung festzulegen.","Das BVerfG erlaubt nun assistierten Suizid als Teil des Persönlichkeitsrechts.","Das Recht auf selbstbestimmtes Sterben wurde 2020 verfassungsrechtlich anerkannt.","Das BVerfG hat §217 StGB gekippt und damit Sterbehilfe erleichtert."],"correctAnswer":"Das Bundesverfassungsgericht hat 2020 einen Paradigmenwechsel in der deutschen Sterbehilfejurisprudenz eingeleitet: Mit der Anerkennung eines Rechts auf selbstbestimmtes Sterben als Teil des allgemeinen Persönlichkeitsrechts hat es das Spannungsverhältnis zwischen staatlichem Lebensschutz und individueller Autonomie zugunsten letzterer verschoben — eine Entscheidung, die den Gesetzgeber zur Neuregulierung verpflichtet, ohne die inhaltliche Ausgestaltung festzulegen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Urteil verschiebt das Gleichgewicht zugunsten individueller ___.","options":["Freiheitsrechte","Rechte","Interessen","Ansprüche"],"correctAnswer":"Freiheitsrechte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The reform shifts responsibility in favour of the municipalities","wordBankItems":["Die","Reform","verschiebt","die","Zuständigkeit","zugunsten","der","Kommunen","."],"correctAnswer":"Die Reform verschiebt die Zuständigkeit zugunsten der Kommunen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Untrennbar'' means?","options":["inseparably","indivisibly","inextricably","unbeatably"],"correctAnswer":"inseparably"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002f6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss reproductive medicine at B2","Use Reproduktionsmedizin vocabulary","Talk about IVF, surrogacy, egg donation, and Germany''s reproductive law"],"explanation":{"intro":"Reproductive medicine vocabulary covers IVF, surrogacy, egg donation, and Germany''s strict reproductive law at B2.","culturalNote":"Reproduktionsmedizin: Germany: Embryonenschutzgesetz (ESchG — 1990 — strict embryo protection — no egg donation, no surrogacy — very restrictive for Europe — allows IVF but only 3 eggs fertilised per cycle, no preimplantation genetic diagnosis until 2011). Key: In-vitro-Fertilisation (IVF — Louise Brown 1978 — first test-tube baby). Präimplantationsdiagnostik (PID — preimplantation genetic diagnosis — legally restricted in Germany — only if heritable disease risk). Leihmutterschaft (surrogacy — illegal in Germany — commercial and altruistic). Eizellspende (egg donation — illegal in Germany). Key tension: Kinderwunsch (desire for a child — Recht auf ein Kind?) vs. Embryonenschutz (embryo protection — embryo as potential life from fertilisation). Gay parenthood (same-sex — Lebenspartnerschaft — adoption allowed since 2013 — step-child adoption 2009). Key comparative: Netherlands, Spain, Belgium much more liberal. Reproduktive Gerechtigkeit (reproductive justice — feminist concept)."},"examples":[{"german":"Das Embryonenschutzgesetz spiegelt eine konservative Position in der Frage des moralischen Status von Embryonen wider: Es behandelt den Embryo ab dem Moment der Befruchtung als schutzwürdiges menschliches Leben und beschränkt damit Praktiken der assistierten Reproduktion, die in anderen europäischen Ländern selbstverständlich sind — eine Restriktion, die medizinisch und verfassungsrechtlich immer stärker herausgefordert wird.","english":"The Embryo Protection Act reflects a conservative position on the question of the moral status of embryos: it treats the embryo from the moment of fertilisation as human life worthy of protection and thereby restricts practices of assisted reproduction that are considered natural in other European countries — a restriction that is increasingly challenged medically and constitutionally."},{"german":"Reproduktive Gerechtigkeit ist ein intersektionaler Begriff: Er verbindet das Recht, Kinder zu haben, mit dem Recht, keine Kinder zu haben, und dem Recht, Kinder unter sicheren und würdevollen Bedingungen aufzuziehen — eine Konzeption, die über reproduktiven Selbstbestimmung hinausgeht und Fragen der Gesundheitsversorgung, ökonomischen Teilhabe und sozialen Unterstützung einschließt.","english":"Reproductive justice is an intersectional concept: it links the right to have children with the right not to have children, and the right to raise children under safe and dignified conditions — a conception that goes beyond reproductive self-determination and includes questions of healthcare, economic participation, and social support."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Embryo Protection Act, surrogacy prohibition, and reproductive justice at B2."}}',
'{"items":[{"word":"schutzwürdig","translation":"worthy of protection","pronunciation":"SHOOTS-vür-dikh","example":"Schutzwürdiges Leben."},{"word":"selbstverständlich","translation":"natural/taken for granted","pronunciation":"ZELPST-fer-shtent-likh","example":"Selbstverständliche Praxis."},{"word":"intersektional","translation":"intersectional","pronunciation":"in-ter-sek-tsyoh-NAHL","example":"Intersektionaler Begriff."},{"word":"die Teilhabe","translation":"participation","pronunciation":"dee TYL-hah-beh","example":"Ökonomische Teilhabe."},{"word":"einschließen","translation":"to include","pronunciation":"YN-shlee-sen","example":"Fragen einschließen."},{"word":"die Konzeption","translation":"conception/concept","pronunciation":"dee kon-tsep-TSYOHN","example":"Weitreichende Konzeption."}]}',
'{"title":"Über X hinausgehen und Y einschließen — to go beyond X and include Y","pattern":"etwas geht über X hinaus und schließt Y ein = something goes beyond X and includes Y (hinausgehen über = to go beyond — marks extension beyond a prior boundary; einschließen = to include — marks what is added)","explanation":"Hinausgehen über = to go beyond (hinausgehen — separable: geht...hinaus; über + accusative = beyond). Einschließen = to include (separable: schließt...ein; marks inclusion of Y within the extended scope). Eine Konzeption, die über X hinausgeht und Y einschließt = a conception that goes beyond X and includes Y. The pattern marks an expansion: first the existing boundary (X) is exceeded, then the new scope (Y) is specified. Widely used when defining an extended or fuller concept. Compare: über X hinausgehen (to go beyond X — without specifying what is added), mehr als X umfassen (to encompass more than X), sich erstrecken auf (to extend to), Y zusätzlich berücksichtigen (additionally consider Y).","examples":[{"sentence":"Das Konzept geht über Umweltschutz hinaus und schließt soziale Gerechtigkeit ein.","translation":"The concept goes beyond environmental protection and includes social justice."},{"sentence":"Die Analyse geht über Wirtschaft hinaus und schließt politische Faktoren ein.","translation":"The analysis goes beyond economics and includes political factors."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schutzwürdig'' means?","options":["worthy of protection","protected","deserving protection","protectable"],"correctAnswer":"worthy of protection"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Reproductive justice is an intersectional concept: it links the right to have children with the right not to have children, and the right to raise children under safe and dignified conditions — a conception that goes beyond reproductive self-determination and includes questions of healthcare, economic participation, and social support.","options":["Reproduktive Gerechtigkeit ist ein intersektionaler Begriff: Er verbindet das Recht, Kinder zu haben, mit dem Recht, keine Kinder zu haben, und dem Recht, Kinder unter sicheren und würdevollen Bedingungen aufzuziehen — eine Konzeption, die über reproduktiven Selbstbestimmung hinausgeht und Fragen der Gesundheitsversorgung, ökonomischen Teilhabe und sozialen Unterstützung einschließt.","Reproduktive Gerechtigkeit geht über das Recht auf Abtreibung hinaus.","Reproduktive Rechte umfassen nicht nur Verhütung und Abtreibung, sondern auch Elternschaft.","Reproduktive Gerechtigkeit ist intersektional: es geht um Gesundheit, Ökonomie und Soziales."],"correctAnswer":"Reproduktive Gerechtigkeit ist ein intersektionaler Begriff: Er verbindet das Recht, Kinder zu haben, mit dem Recht, keine Kinder zu haben, und dem Recht, Kinder unter sicheren und würdevollen Bedingungen aufzuziehen — eine Konzeption, die über reproduktiven Selbstbestimmung hinausgeht und Fragen der Gesundheitsversorgung, ökonomischen Teilhabe und sozialen Unterstützung einschließt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Konzept geht über Umweltschutz hinaus und schließt soziale Gerechtigkeit ___.","options":["ein","an","aus","vor"],"correctAnswer":"ein"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The analysis goes beyond economics and includes political factors","wordBankItems":["Die","Analyse","geht","über","Wirtschaft","hinaus","und","schließt","politische","Faktoren","ein","."],"correctAnswer":"Die Analyse geht über Wirtschaft hinaus und schließt politische Faktoren ein ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Intersektional'' means?","options":["intersectional","cross-cutting","overlapping","multi-dimensional"],"correctAnswer":"intersectional"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002f7',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss care and care work at B2","Use Pflege und Sorgearbeit vocabulary","Talk about Germany''s care crisis, unpaid care work, and the feminist care economy debate"],"explanation":{"intro":"Care and care work vocabulary covers Germany''s care crisis, unpaid care work inequality, and feminist care economics at B2.","culturalNote":"Pflege und Sorgearbeit: Germany: Pflegeversicherung (statutory long-term care insurance — 1995 — 5th pillar of social insurance — Bismarck system). Key: 4.1 million Pflegebedürftige (people needing care — 2021). Pflegekräfte (care workers — 1.8 million — 85% Frauen). Fachkräftemangel in der Pflege (care worker shortage — severe). Migrant care workers (especially Eastern European — often informal/grey market). Key: Sorgearbeit (care work — broader: includes childcare, eldercare, domestic work — feminist concept). Unbezahlte Sorgearbeit (unpaid care work — women do 87 min/day more than men — SOEP data). Carol Gilligan — ethics of care (care as moral principle). Key policy debate: Pflegereform (reform — inadequate current funding — DPR). Key: Caring Masculinities (männliche Fürsorge — challenging gender norms). Second shift (Doppelbelastung — double burden of paid and unpaid work). Defamilialisierung (defamilialisation — transferring care from family to public institutions)."},"examples":[{"german":"Sorgearbeit ist das unsichtbare Fundament der Gesellschaft: Ohne die unbezahlte oder unterbezahlte Arbeit der Betreuung, Erziehung und Pflege könnten weder Erwerbswirtschaft noch Sozialstaat funktionieren — aber diese Arbeit wird in ökonomischen Kennziffern nicht erfasst, politisch unterprioritisiert und gesellschaftlich abgewertet, weil sie überwiegend von Frauen geleistet wird und damit mit einer historischen Geringschätzung belastet ist.","english":"Care work is the invisible foundation of society: without the unpaid or underpaid work of looking after, raising, and caring, neither the paid economy nor the welfare state could function — but this work is not captured in economic indicators, is politically under-prioritised, and is socially devalued because it is predominantly performed by women and is thereby burdened with a historical undervaluation."},{"german":"Die Pflegekrise hat strukturelle Ursachen, die über Lohnfragen hinausgehen: Ein Pflegesystem, das auf der Bereitschaft von Familienangehörigen — überwiegend Frauen — zur unentgeltlichen Fürsorge aufgebaut ist, externalisiert gesellschaftliche Kosten auf private Haushalte und konserviert Geschlechterungleichheiten. Nachhaltiger Pflegeschutz erfordert eine Degendering der Sorgearbeit und professionelle Vergütung ihrer Leistungen.","english":"The care crisis has structural causes that go beyond wage questions: a care system built on the willingness of family members — predominantly women — for unpaid care externalises social costs onto private households and perpetuates gender inequalities. Sustainable care protection requires a degendering of care work and professional remuneration of its services."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s care crisis, unpaid care work inequality, and defamilialisation at B2."}}',
'{"items":[{"word":"die Sorgearbeit","translation":"care work","pronunciation":"dee ZOR-geh-ar-byt","example":"Unbezahlte Sorgearbeit."},{"word":"die Kennziffer","translation":"indicator","pronunciation":"dee KEN-tsif-fer","example":"Ökonomische Kennziffern."},{"word":"abwerten","translation":"to devalue","pronunciation":"AB-ver-ten","example":"Gesellschaftlich abwerten."},{"word":"unentgeltlich","translation":"unpaid/free of charge","pronunciation":"oon-ent-GELT-likh","example":"Unentgeltliche Fürsorge."},{"word":"externalisieren","translation":"to externalise","pronunciation":"eks-ter-na-li-ZEE-ren","example":"Kosten externalisieren."},{"word":"die Vergütung","translation":"remuneration","pronunciation":"dee fer-GÜ-toong","example":"Professionelle Vergütung."}]}',
'{"title":"Etwas ist mit X belastet — something is burdened with X (carries the weight of X)","pattern":"etwas ist mit X belastet = something is burdened with X (belastet = burdened — past participle of belasten used as stative predicate; mit + dative = with X — marks what weighs on the subject)","explanation":"Belastet sein mit = to be burdened with (belasten = to burden; belastet = burdened; mit + dative = with X). X ist mit Y belastet = X is burdened with Y. The phrase marks that something carries a historical, moral, or structural weight that affects how it is perceived or functions. Sorgearbeit ist mit einer historischen Geringschätzung belastet = care work is burdened with a historical undervaluation. Compare: X ist durch Y belastet (X is burdened through Y — more causal: Y created the burden), X ist durch Y geprägt (X is shaped by Y — less negative), X steht unter dem Zeichen von Y (X stands under the sign of Y — more symbolic), X trägt die Last von Y (X bears the burden of Y — more active/agentive).","examples":[{"sentence":"Diese Diskussion ist mit historischen Vorurteilen belastet.","translation":"This discussion is burdened with historical prejudices."},{"sentence":"Das Thema ist mit emotionalen Konnotationen belastet.","translation":"The topic is burdened with emotional connotations."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unentgeltlich'' means?","options":["unpaid/free of charge","voluntary","gratuitous","free"],"correctAnswer":"unpaid/free of charge"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Care work is the invisible foundation of society: without the unpaid or underpaid work of looking after, raising, and caring, neither the paid economy nor the welfare state could function — but this work is not captured in economic indicators, is politically under-prioritised, and is socially devalued because it is predominantly performed by women and is thereby burdened with a historical undervaluation.","options":["Sorgearbeit ist das unsichtbare Fundament der Gesellschaft: Ohne die unbezahlte oder unterbezahlte Arbeit der Betreuung, Erziehung und Pflege könnten weder Erwerbswirtschaft noch Sozialstaat funktionieren — aber diese Arbeit wird in ökonomischen Kennziffern nicht erfasst, politisch unterprioritisiert und gesellschaftlich abgewertet, weil sie überwiegend von Frauen geleistet wird und damit mit einer historischen Geringschätzung belastet ist.","Unbezahlte Fürsorgearbeit wird in der Volkswirtschaft nicht sichtbar gemacht.","Sorgearbeit ist weiblich konnotiert und deshalb gesellschaftlich abgewertet.","Ohne Sorgearbeit von Frauen würde Wirtschaft und Sozialstaat zusammenbrechen."],"correctAnswer":"Sorgearbeit ist das unsichtbare Fundament der Gesellschaft: Ohne die unbezahlte oder unterbezahlte Arbeit der Betreuung, Erziehung und Pflege könnten weder Erwerbswirtschaft noch Sozialstaat funktionieren — aber diese Arbeit wird in ökonomischen Kennziffern nicht erfasst, politisch unterprioritisiert und gesellschaftlich abgewertet, weil sie überwiegend von Frauen geleistet wird und damit mit einer historischen Geringschätzung belastet ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Diskussion ist mit historischen Vorurteilen ___.","options":["belastet","behaftet","geprägt","beschwert"],"correctAnswer":"belastet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The topic is burdened with emotional connotations","wordBankItems":["Das","Thema","ist","mit","emotionalen","Konnotationen","belastet","."],"correctAnswer":"Das Thema ist mit emotionalen Konnotationen belastet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Externalisieren'' means?","options":["to externalise","to outsource","to transfer","to offload"],"correctAnswer":"to externalise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002f8',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss disability and inclusion at B2","Use Behinderung und Inklusion vocabulary","Talk about UN CRPD, Germany''s disability policy, and inclusive education debate"],"explanation":{"intro":"Disability and inclusion vocabulary covers UN CRPD, Germany''s disability law, and inclusive education at B2.","culturalNote":"Behinderung und Inklusion: Germany: UN-Behindertenrechtskonvention (UNCRPD — UN Convention on Rights of Persons with Disabilities — ratified 2009 — Germany bound). Key: medical model vs. social model of disability (medical: impairment is the problem; social: barriers created by society are the problem). SGB IX (Social Code Book IX — disability integration into work). Schwerbehindertenausweis (severely disabled person ID — benefits). Inklusion in der Schule (inclusive education — UNCRPD Art. 24 — controversial implementation in Germany — Sonderschulen vs. inclusive mainstream schools). Sonderpädagogik (special education — Germany has high proportion in Förderschulen — 4.5% — EU avg 2.5%). Ableismus (ableism — discrimination based on disability). Barrierefreiheit (accessibility — DIN standards). BVerfG: Recht auf Inklusion. Key figures: Ottmar Miles-Paul. 7.8 million Schwerbehinderte in Germany."},"examples":[{"german":"Das soziale Modell von Behinderung markiert einen konzeptionellen Paradigmenwechsel: Nicht die körperliche oder geistige Beeinträchtigung konstituiert die Behinderung, sondern die gesellschaftlich konstruierten Barrieren — bauliche, kommunikative, attitudinale — die Menschen mit Beeinträchtigungen von voller Teilhabe ausschließen. Behinderung ist damit nicht primär ein medizinisches, sondern ein gesellschaftliches und politisches Problem.","english":"The social model of disability marks a conceptual paradigm shift: it is not the physical or mental impairment that constitutes the disability, but the socially constructed barriers — structural, communicative, attitudinal — that exclude people with impairments from full participation. Disability is thereby not primarily a medical, but a social and political problem."},{"german":"Die Inklusionsdebatte in der Bildung ist nicht nur eine pädagogische, sondern eine gerechtigkeitstheoretische Frage: Das Prinzip der gemeinsamen Beschulung von Kindern mit und ohne Behinderung verfolgt nicht nur das Ziel höherer Lernleistungen, sondern die Normalisierung von Diversität — eine Schule, in der Verschiedenheit als Normalfall erlebt wird, bereitet auf eine inklusive Gesellschaft vor, in der Barrierefreiheit als Standard gilt, nicht als Ausnahme.","english":"The inclusion debate in education is not only a pedagogical, but a justice-theoretical question: the principle of joint schooling of children with and without disabilities pursues not only the goal of higher learning performance, but the normalisation of diversity — a school in which difference is experienced as the normal case prepares for an inclusive society in which accessibility is the standard, not the exception."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the social model of disability, inclusive education, and ableism at B2."}}',
'{"items":[{"word":"die Beeinträchtigung","translation":"impairment","pronunciation":"dee beh-YN-trekh-ti-goong","example":"Körperliche Beeinträchtigung."},{"word":"konstituieren","translation":"to constitute","pronunciation":"kon-sti-too-EE-ren","example":"Die Behinderung konstituieren."},{"word":"attitudinal","translation":"attitudinal","pronunciation":"ah-ti-tü-di-NAHL","example":"Attitudinale Barrieren."},{"word":"die Barrierefreiheit","translation":"accessibility","pronunciation":"dee ba-RYEH-reh-fry-hyt","example":"Barrierefreiheit als Standard."},{"word":"die Beschulung","translation":"schooling","pronunciation":"dee beh-SHOO-loong","example":"Gemeinsame Beschulung."},{"word":"der Normalfall","translation":"normal case","pronunciation":"dayr NOR-mal-fal","example":"Als Normalfall erleben."}]}',
'{"title":"Etwas als Normalfall erleben vs. als Ausnahme — to experience as the normal case vs. as the exception","pattern":"etwas als Normalfall erleben = to experience something as the normal case (als Normalfall erleben = to experience X as normal; Normalfall = normal case, the expected default; contrasts with als Ausnahme = as the exception)","explanation":"Als Normalfall erleben = to experience as the normal case (erleben = to experience — subjective/experiential; als = as — classification). Normalfall = normal case (the expected, default state). The contrast structure: als Normalfall (as the norm) vs. als Ausnahme (as the exception). A Schule, in der Verschiedenheit als Normalfall erlebt wird = a school in which difference is experienced as the norm. The pattern is normative: it argues for changing what counts as ''normal.'' Compare: als Normalität behandeln (to treat as normality — more active/policy-oriented), zur Norm machen (to make the norm — more transformative), als Selbstverständlichkeit betrachten (to regard as self-evident — stronger normalisation), als Standard etablieren (to establish as standard — more institutional).","examples":[{"sentence":"Diversität sollte als Normalfall, nicht als Ausnahme erlebt werden.","translation":"Diversity should be experienced as the normal case, not as the exception."},{"sentence":"Wir wollen, dass Mehrsprachigkeit als Normalfall gilt.","translation":"We want multilingualism to count as the normal case."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Konstituieren'' means?","options":["to constitute","to establish","to create","to define"],"correctAnswer":"to constitute"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The social model of disability marks a conceptual paradigm shift: it is not the physical or mental impairment that constitutes the disability, but the socially constructed barriers — structural, communicative, attitudinal — that exclude people with impairments from full participation. Disability is thereby not primarily a medical, but a social and political problem.","options":["Das soziale Modell von Behinderung markiert einen konzeptionellen Paradigmenwechsel: Nicht die körperliche oder geistige Beeinträchtigung konstituiert die Behinderung, sondern die gesellschaftlich konstruierten Barrieren — bauliche, kommunikative, attitudinale — die Menschen mit Beeinträchtigungen von voller Teilhabe ausschließen. Behinderung ist damit nicht primär ein medizinisches, sondern ein gesellschaftliches und politisches Problem.","Nicht das Individuum, sondern die Gesellschaft erzeugt Behinderung durch Barrieren.","Das soziale Modell verschiebt die Verantwortung von betroffenen Personen auf die Gesellschaft.","Inklusion bedeutet: Barrieren abbauen, nicht Menschen anpassen."],"correctAnswer":"Das soziale Modell von Behinderung markiert einen konzeptionellen Paradigmenwechsel: Nicht die körperliche oder geistige Beeinträchtigung konstituiert die Behinderung, sondern die gesellschaftlich konstruierten Barrieren — bauliche, kommunikative, attitudinale — die Menschen mit Beeinträchtigungen von voller Teilhabe ausschließen. Behinderung ist damit nicht primär ein medizinisches, sondern ein gesellschaftliches und politisches Problem."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diversität sollte als Normalfall, nicht als ___ erlebt werden.","options":["Ausnahme","Abweichung","Besonderheit","Unterschied"],"correctAnswer":"Ausnahme"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We want multilingualism to count as the normal case","wordBankItems":["Wir","wollen",",","dass","Mehrsprachigkeit","als","Normalfall","gilt","."],"correctAnswer":"Wir wollen , dass Mehrsprachigkeit als Normalfall gilt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Barrierefreiheit'' means?","options":["accessibility","barrier-free access","freedom from barriers","access for all"],"correctAnswer":"accessibility"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_curriculum_lesson_plans (id, curriculum_id, level_id, unit_id, stable_ref, position, title, topic, plan_status) VALUES
